-- ── story 9-2: the notification panel ─────────────────────────────────────
-- Generated by drizzle-kit (the two tables, the episode column, the indexes)
-- and hand-amended below the marker: the CHECKs, RLS and the post-migration
-- probe (drizzle-kit is blind to all three; `bun run db:generate` afterwards
-- reports "No schema changes").
--
-- Additive only: two new tables (written only by the notifications module)
-- and one nullable column on `integrations` (the channels module's open
-- sync-health episode). No data statement — no pre-flight, no fail-fast.
CREATE TABLE "notification_reads" (
	"tenant_id" uuid NOT NULL,
	"user_id" uuid NOT NULL,
	"last_opened_at" timestamp with time zone NOT NULL,
	CONSTRAINT "notification_reads_tenant_id_user_id_pk" PRIMARY KEY("tenant_id","user_id")
);
--> statement-breakpoint
CREATE TABLE "notifications" (
	"id" uuid PRIMARY KEY NOT NULL,
	"tenant_id" uuid NOT NULL,
	"source_type" text NOT NULL,
	"source_id" uuid NOT NULL,
	"warehouse_id" uuid,
	"summary" jsonb,
	"raised_at" timestamp with time zone,
	"surfaced_at" timestamp with time zone,
	"resolved_at" timestamp with time zone,
	"resolution" text,
	"created_at" timestamp with time zone DEFAULT now() NOT NULL,
	"updated_at" timestamp with time zone DEFAULT now() NOT NULL
);
--> statement-breakpoint
ALTER TABLE "integrations" ADD COLUMN "sync_episode_id" uuid;--> statement-breakpoint
CREATE UNIQUE INDEX "notifications_tenant_source_unique" ON "notifications" USING btree ("tenant_id","source_type","source_id");--> statement-breakpoint
CREATE INDEX "notifications_tenant_raised_at_id_idx" ON "notifications" USING btree ("tenant_id","raised_at" DESC NULLS LAST,"id" DESC NULLS LAST);--> statement-breakpoint
-- ── hand-amended: the controlled vocabulary (IMPLEMENTATION-GUIDE §4) ─────
-- Pinned against `NOTIFICATION_SOURCE_TYPES` (modules/notifications) by
-- test/notifications.spec.ts. `source_type` is NOT NULL, so the bare IN arm
-- cannot pass on a NULL.
ALTER TABLE "notifications" ADD CONSTRAINT "notifications_source_type_check" CHECK ("source_type" IN (
	'stock-adjustment', 'count-variance', 'over-receipt', 'rejected-op',
	'reorder-breach', 'batch-alert', 'qc-hold', 'channel-sync'
));--> statement-breakpoint
-- ── hand-amended: the row shape ──────────────────────────────────────────
-- (1) a raised row (summary set) carries both instants;
-- (2) a tombstone (summary null) exists only because a resolve arrived — it
--     is always resolved;
-- (3) `resolved_at` and `resolution` are set together or not at all.
ALTER TABLE "notifications" ADD CONSTRAINT "notifications_shape_check" CHECK (
	("summary" IS NULL OR ("raised_at" IS NOT NULL AND "surfaced_at" IS NOT NULL))
	AND ("summary" IS NOT NULL OR "resolved_at" IS NOT NULL)
	AND (("resolved_at" IS NULL) = ("resolution" IS NULL))
);--> statement-breakpoint
-- ── hand-amended: RLS — the uniform tenant policy (the 0056 shape) ─────────
ALTER TABLE "notifications" ENABLE ROW LEVEL SECURITY;--> statement-breakpoint
ALTER TABLE "notification_reads" ENABLE ROW LEVEL SECURITY;--> statement-breakpoint
CREATE POLICY "notifications_tenant_isolation" ON "notifications"
	USING ("tenant_id" = NULLIF(current_setting('app.tenant_id', true), '')::uuid)
	WITH CHECK ("tenant_id" = NULLIF(current_setting('app.tenant_id', true), '')::uuid);--> statement-breakpoint
CREATE POLICY "notification_reads_tenant_isolation" ON "notification_reads"
	USING ("tenant_id" = NULLIF(current_setting('app.tenant_id', true), '')::uuid)
	WITH CHECK ("tenant_id" = NULLIF(current_setting('app.tenant_id', true), '')::uuid);--> statement-breakpoint
-- ── the post-migration assertion (the 0064/0066 model) ────────────────────
-- The accepted shapes are inserted first and rolled back by a sentinel, so a
-- CHECK that refuses everything cannot pass. Each refused shape runs in its
-- own subtransaction and must be refused by `check_violation` ON THE NAMED
-- CONSTRAINT — a probe another CHECK happens to refuse proves nothing.
DO $$
DECLARE
	t uuid := gen_random_uuid();
	refused_by text;
	expected text;
	probe text;
BEGIN
	-- (1) the accepted shapes: an open raised entry for every source type, a
	-- resolved raised entry, and a tombstone (a resolve before its raise).
	BEGIN
		INSERT INTO "notifications" ("id","tenant_id","source_type","source_id","warehouse_id","summary","raised_at","surfaced_at","resolved_at","resolution")
		VALUES (gen_random_uuid(), t, 'stock-adjustment', gen_random_uuid(), t, '{}'::jsonb, now(), now(), NULL, NULL),
		       (gen_random_uuid(), t, 'count-variance', gen_random_uuid(), t, '{}'::jsonb, now(), now(), NULL, NULL),
		       (gen_random_uuid(), t, 'over-receipt', gen_random_uuid(), t, '{}'::jsonb, now(), now(), now(), 'approved'),
		       (gen_random_uuid(), t, 'rejected-op', gen_random_uuid(), NULL, '{}'::jsonb, now(), now(), NULL, NULL),
		       (gen_random_uuid(), t, 'reorder-breach', gen_random_uuid(), t, '{}'::jsonb, now(), now(), NULL, NULL),
		       (gen_random_uuid(), t, 'batch-alert', gen_random_uuid(), t, '{}'::jsonb, now(), now(), NULL, NULL),
		       (gen_random_uuid(), t, 'qc-hold', gen_random_uuid(), t, '{}'::jsonb, now(), now(), NULL, NULL),
		       (gen_random_uuid(), t, 'channel-sync', gen_random_uuid(), NULL, NULL, NULL, NULL, now(), 'recovered');
		RAISE EXCEPTION USING ERRCODE = 'P0067', MESSAGE = 'rollback the accepted probes';
	EXCEPTION
		WHEN check_violation THEN
			RAISE EXCEPTION 'migration 0067: an accepted notification shape was refused.';
		WHEN SQLSTATE 'P0067' THEN
			NULL; -- the accepted shapes landed, and the sentinel rolled them back
	END;
	-- (2) the refused shapes, each by its named constraint.
	FOREACH probe IN ARRAY ARRAY[
		'unknown source type',
		'raised without raised_at',
		'raised without surfaced_at',
		'unresolved tombstone',
		'resolved without a resolution',
		'a resolution without resolved_at'
	] LOOP
		refused_by := NULL;
		expected := CASE probe WHEN 'unknown source type' THEN 'notifications_source_type_check' ELSE 'notifications_shape_check' END;
		BEGIN
			CASE probe
				WHEN 'unknown source type' THEN
					INSERT INTO "notifications" ("id","tenant_id","source_type","source_id","summary","raised_at","surfaced_at")
					VALUES (gen_random_uuid(), t, 'task-assignment', gen_random_uuid(), '{}'::jsonb, now(), now());
				WHEN 'raised without raised_at' THEN
					INSERT INTO "notifications" ("id","tenant_id","source_type","source_id","summary","raised_at","surfaced_at")
					VALUES (gen_random_uuid(), t, 'qc-hold', gen_random_uuid(), '{}'::jsonb, NULL, now());
				WHEN 'raised without surfaced_at' THEN
					INSERT INTO "notifications" ("id","tenant_id","source_type","source_id","summary","raised_at","surfaced_at")
					VALUES (gen_random_uuid(), t, 'qc-hold', gen_random_uuid(), '{}'::jsonb, now(), NULL);
				WHEN 'unresolved tombstone' THEN
					INSERT INTO "notifications" ("id","tenant_id","source_type","source_id","summary")
					VALUES (gen_random_uuid(), t, 'qc-hold', gen_random_uuid(), NULL);
				WHEN 'resolved without a resolution' THEN
					INSERT INTO "notifications" ("id","tenant_id","source_type","source_id","summary","raised_at","surfaced_at","resolved_at","resolution")
					VALUES (gen_random_uuid(), t, 'qc-hold', gen_random_uuid(), '{}'::jsonb, now(), now(), now(), NULL);
				WHEN 'a resolution without resolved_at' THEN
					INSERT INTO "notifications" ("id","tenant_id","source_type","source_id","summary","raised_at","surfaced_at","resolved_at","resolution")
					VALUES (gen_random_uuid(), t, 'qc-hold', gen_random_uuid(), '{}'::jsonb, now(), now(), NULL, 'released');
			END CASE;
		EXCEPTION WHEN check_violation THEN
			GET STACKED DIAGNOSTICS refused_by = CONSTRAINT_NAME;
		END;
		IF refused_by IS NULL THEN
			RAISE EXCEPTION 'migration 0067: the CHECK probe "%" was not refused.', probe;
		END IF;
		IF refused_by <> expected THEN
			RAISE EXCEPTION 'migration 0067: the CHECK probe "%" was refused by % — expected %.', probe, refused_by, expected;
		END IF;
	END LOOP;
	IF EXISTS (SELECT 1 FROM "notifications" WHERE "tenant_id" = t) THEN
		RAISE EXCEPTION 'migration 0067: a CHECK probe row survived.';
	END IF;
END $$;
